#nullable enable
using CompMs.Common.StructureFinder.DiagnosticRules.Json;
using CompMs.Common.StructureFinder.DiagnosticRules.Loading;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;

namespace CompMs.Common.StructureFinder.DiagnosticRules.Tests;

/// <summary>
/// The parity vectors <c>cjson-vectors.json</c>, generated by the MS-DIAL spectrum catalog
/// (<c>tools/ws8_p3/cjson_vectors.py</c>, CPython as the oracle) and copied unchanged into
/// Resources\DiagnosticRuleFixtures with its SOURCE.md. A test that needs them is Inconclusive, never passed,
/// when they are missing.
/// </summary>
internal static class DiagnosticRuleFixtures
{
    public const string FixtureDirectory = @"Resources\DiagnosticRuleFixtures";
    public const string VectorFile = "cjson-vectors.json";

    /// <summary>The sha256 SOURCE.md names: the vectors of catalog commit 150e09e.</summary>
    public const string VectorSha256 = "942ca00774cf87c2242761b03befa870c116b549e4a361e04ee2070b3620e0c4";

    private static JsonObject? _vectors;

    public static string FixturePath(string name) => Path.Combine(AppDomain.CurrentDomain.BaseDirectory, FixtureDirectory, name);

    public static byte[] VectorBytesOrInconclusive() {
        var path = FixturePath(VectorFile);
        if (!File.Exists(path)) {
            Assert.Inconclusive("cjson-vectors.json not copied from the catalog");
        }
        return File.ReadAllBytes(path);
    }

    public static JsonObject Vectors() => _vectors ??= StrictJsonReader.Read(VectorBytesOrInconclusive());

    public static JsonArray Section(string name) => (JsonArray)Vectors()[name];

    public static string Str(JsonValue v) => ((JsonString)v).Value;

    public static string Str(JsonObject o, string key) => ((JsonString)o[key]).Value;

    public static long Int(JsonObject o, string key) => ((JsonInteger)o[key]).Value;

    public static byte[] B64(JsonValue v) => Convert.FromBase64String(Str(v));

    public static double FromHex(string hex) => BitConverter.Int64BitsToDouble(unchecked((long)ulong.Parse(hex, NumberStyles.HexNumber, CultureInfo.InvariantCulture)));

    public static string FromUtf16Hex(string hex) {
        var sb = new StringBuilder();
        for (var i = 0; i < hex.Length; i += 4) {
            sb.Append((char)int.Parse(hex.Substring(i, 4), NumberStyles.HexNumber, CultureInfo.InvariantCulture));
        }
        return sb.ToString();
    }

    /// <summary>A {path: base64} object as a file map.</summary>
    public static Dictionary<string, byte[]> Files(JsonObject map) {
        var files = new Dictionary<string, byte[]>(StringComparer.Ordinal);
        foreach (var m in map.Members) {
            files[m.Key] = Convert.FromBase64String(Str(m.Value));
        }
        return files;
    }

    /// <summary>The loader-error base files updated by a patch (null removes a path).</summary>
    public static Dictionary<string, byte[]> Patched(JsonObject baseFiles, JsonObject patch) {
        var files = Files(baseFiles);
        foreach (var m in patch.Members) {
            if (m.Value is JsonNull) {
                files.Remove(m.Key);
            }
            else {
                files[m.Key] = Convert.FromBase64String(Str(m.Value));
            }
        }
        return files;
    }

    public static string ErrorList(IEnumerable<RuleLoadError> errors) => string.Join("\n", errors.Select(e => e.ToString()));

    public static string ErrorList(JsonArray expected) =>
        string.Join("\n", expected.Select(e => string.Join("\t", ((JsonArray)e).Select(Str))));

    /// <summary>Runs <paramref name="read"/> with the calling thread's culture set to <paramref name="culture"/>.</summary>
    public static T Under<T>(CultureInfo culture, Func<T> read) {
        var thread = Thread.CurrentThread;
        var saved = thread.CurrentCulture;
        var savedUi = thread.CurrentUICulture;
        try {
            thread.CurrentCulture = culture;
            thread.CurrentUICulture = culture;
            return read();
        }
        finally {
            thread.CurrentCulture = saved;
            thread.CurrentUICulture = savedUi;
        }
    }
}
